styleBlocks.css:
body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

select {
  background-color: var(--select-surface);
  color: var(--text-primary);
  color-scheme: dark;
}

select option,
select optgroup {
  background-color: var(--select-popup-surface);
  color: var(--text-primary);
}

.modal {
  position: relative; cursor: default;
  background: var(--bg-secondary); border-radius: var(--radius);
  border: 1px solid var(--border); width: 90%; max-width: 700px;
  max-height: 85vh; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; padding: 32px;
  transform: scale(0.96) translateY(8px); opacity: 0;
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.gb-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 22px 26px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 92%, var(--bg-card));
}

.gb-modal-kicker {
  font-family: var(--font-mono);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.gb-modal-title {
  margin-top: 3px;
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0;
}

.gb-modal-head .modal-close {
  position: static;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 22px;
  line-height: 1;
  padding: 0;
  flex-shrink: 0;
}

.gb-modal-head .modal-close:hover {
  color: var(--text-primary);
  border-color: var(--accent);
  background: var(--bg-hover);
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > h3:first-of-type,
.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > .modal-header:first-child {
  margin: -32px -32px 20px;
  padding: 22px 56px 18px 26px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 92%, var(--bg-card));
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) > h3:first-of-type {
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0;
}

.modal:not(.marker-detail-modal):not(.gb-form-modal):not(.gb-history-modal):not(.settings-modal) .modal-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
  padding-top: 16px;
  border-top: 1px solid var(--border);
}

.modal-close {
  position: absolute; top: 16px; right: 16px;
  background: none; border: none; color: var(--text-muted);
  font-size: 24px; cursor: pointer; padding: 0 4px;
}

.modal .modal-unit {
  color: var(--text-muted); font-size: 14px; margin-bottom: 8px;
  /* Source-name + delta + trend separated by middle-dots; let them wrap
     gracefully on narrow viewports rather than overflow the modal box. */
  display: flex; flex-wrap: wrap; gap: 4px 6px; align-items: center;
}

.dashboard-sticky-actions .dashboard-action-btn {
  pointer-events: auto;
  background: color-mix(in srgb, var(--bg-secondary) 88%, transparent);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
}

.dashboard-sticky-actions .dashboard-action-btn-primary {
  background: var(--accent);
  border-color: transparent;
  color: var(--on-accent);
}

.dashboard-action-btn {
  padding: 8px 12px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-secondary);
  color: var(--text-primary); font: inherit; font-size: 12px; font-weight: 600;
  cursor: pointer; transition: background 0.15s, border-color 0.15s, transform 0.05s;
}

.dashboard-action-btn-primary {
  background: var(--accent); border-color: transparent; color: var(--on-accent);
}

html:not([data-theme]) .dashboard-action-btn-primary {
  /* White hover text fails against the blue accent during background
     interpolation, so this button snaps directly to the dark hover surface. */
  transition: border-color 0.15s, transform 0.05s;
}

html:not([data-theme]) .dashboard-action-btn-primary:hover {
  background: var(--bg-hover);
  border-color: var(--accent);
  color: #fff;
}

.goals-severity-badge {
  font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 4px;
  white-space: nowrap; flex-shrink: 0; text-transform: uppercase; letter-spacing: 0.3px;
}

.ctx-tag {
  background: var(--bg-card); border: 1px solid var(--border); color: var(--text-secondary);
  font-size: 12px; padding: 6px 14px; border-radius: 20px; cursor: pointer;
  font-family: inherit; transition: all 0.15s; white-space: nowrap;
}

.ctx-tag.active {
  background: rgba(79, 140, 255, 0.15); border-color: var(--accent); color: var(--accent); font-weight: 600;
}

.m-dashboard-widget-actions .dashboard-action-btn {
    display: inline-flex;
    align-items: center;
    flex: 1 1 auto;
    min-height: 36px;
    justify-content: center;
    text-align: center;
  }

.cycle-icon-btn,
.cycle-action-btn {
  min-width: 36px;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.05s;
}

.cycle-icon-btn:hover,
.cycle-action-btn:hover {
  background: var(--bg-hover);
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  color: var(--text-primary);
}

.cycle-section svg,
.cycle-modal svg {
  display: block;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.cycle-prompt-icon,
.cycle-summary-icon,
.cycle-draw-icon,
.cycle-alert-icon,
.cycle-log-icon {
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--accent);
}

.cycle-draw-phases,
.cycle-period-log,
.cycle-log-meta,
.cycle-symptom-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
}

.cycle-modal {
  width: min(94vw, 780px);
  max-width: 780px;
  max-height: 90vh;
  padding: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
}

.cycle-editor-section {
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-card) 70%, transparent);
}

.cycle-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  min-width: 0;
}

.cycle-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
}

.cycle-field input,
.cycle-field select {
  width: 100%;
  min-height: 38px;
  box-sizing: border-box;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  padding: 8px 10px;
}

.cycle-field input:focus,
.cycle-field select:focus {
  border-color: var(--accent);
  outline: none;
}

.cycle-auto-value {
  min-height: 38px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 10px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 800;
}

.cycle-log-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 14px;
}

.cycle-log-item {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 36px;
  align-items: start;
  gap: 10px;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
}

.cycle-delete-btn:hover {
  border-color: color-mix(in srgb, var(--red) 55%, var(--border));
  color: var(--red);
}

.cycle-add-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 12px;
}

.cycle-add-btn {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  white-space: nowrap;
}

.cycle-symptom-chip.ctx-tag {
  min-height: 30px;
  padding: 5px 10px;
  margin: 0;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
}

.cycle-symptom-chip.ctx-tag:hover {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
  color: var(--text-primary);
}

.cycle-symptom-chip.ctx-tag.active {
  background: var(--accent-fill);
  border-color: var(--accent);
  color: var(--accent);
}

.cycle-modal-footer {
  position: sticky;
  bottom: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 14px 24px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 94%, var(--bg-card));
}

.cycle-danger-btn {
  margin-right: auto;
  color: var(--red);
  border-color: color-mix(in srgb, var(--red) 50%, var(--border));
}

.cycle-modal {
    width: 100%;
    height: calc(100vh - 24px);
    height: calc(100dvh - 24px);
    max-height: none;
  }

.tweaks-head .modal-close {
  position: static;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 22px;
}

